Consider the closed ball $\overline{B_R}$ centered at $0$ with radius $R>0$ in $\mathbb{R}^d$. Then for any $\mu \in V^{p_1,p_2}_K$ and any random variable $X^\mu$ with law $\mu$, we have
    \begin{align*}
        \mu(\overline{B_R}) = \mathbb{P}(X^\mu \in \overline{B_R}) = 1 - \mathbb{P}(|X^\mu|> R)\geq 1 - K/R^{p_2},
    \end{align*}
    by Markov's inequality. $V^{p_1,p_2}_K$ is thus tight. Therefore, by Prokhorov's theorem, for any sequence $\{\mu_n\}_{n\in\mathbb{N}}\subseteq V^{p_1,p_2}_K$, there exists a subsequence $\{\mu_{n_k}\}_{k\in\mathbb{N}}$ and $\mu^*\in \mathcal{P}_{p_1}(\mathbb R^d)$ such that $\mu_{n_k}\to\mu^*$ weakly in the sense that $\int_{\mathbb{R}^d}f(x)\mu_{n_k}(dx) \to \int_{\mathbb{R}^d}f(x)\mu^*(dx)$ as $k\to \infty$, for any bounded and continuous function $f:\mathbb{R}^d \to\mathbb{R}$. Hence, it holds that $\int_{\mathbb{R}^d}\scalerel*[5pt]{\big(}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big(}}}|x|^{p_2}\wedge M\scalerel*[5pt]{\big)}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big)}}}\mu^*(dx)\leq K$ as $\int_{\mathbb{R}^d}\scalerel*[5pt]{\big(}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big(}}}|x|^{p_2}\wedge M\scalerel*[5pt]{\big)}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big)}}}\mu_{n_k}(dx)\leq K$ for any $k \in \mathbb{N}$. Passing $M \to \infty$, the monotone convergence theorem implies that
    $\int_{\mathbb{R}^d} |x|^{p_2} \mu^*(dx)\leq K$, therefore $\mu^* \in V_K^{p_1,p_2}$. 

    We claim that also $\mathcal{W}_{p_1}(\mu_{n_k},\mu) \to 0$. This can be easily seen from the fact (see \cite[Theorem 7.12]{villani_topics_2003}) that $\mathcal{W}_{p_1}(\mu_{n_k},\mu)\to 0$ if and only if
    \begin{enumerate}
        \item[(1).] $\mu_{n_k}\to\mu$ in weak convergence;
        \item[(2).]  $
        \displaystyle\lim_{R\to\infty}\limsup_{k\to\infty}\int_{|x|\geq R}|x|^{p_1} \mu_{n_k}(dx) = 0.$
    \end{enumerate}
    Take a $L^{p_1}$-random variable $X^{n_k}$ with its law $\mathcal{L}(X^{n_k})=\mu_{n_k}$, the second condition in the above follows from the fact that 
    \begin{align*}
        \int_{|x|\geq R}|x|^{p_1} \mu_{n_k}(dx) = \mathbb{E}\Big[|X^{n_k}|^{p_1} \mathds{1}_{\{|X^{n_k}|\geq R\}}\Big]
        \leq&\left\{\mathbb{E}\Big[|X^{n_k}|^{p_2} \Big]\right\}^{p_1/p_2}
        \left\{\mathbb{E}\Big[ \mathds{1}_{\{|X^{n_k}|\geq R\}}\Big]\right\}^{1-p_1/p_2}\\
        \leq&\frac{K}{R^{p_2-p_1}},
    \end{align*}
    hence $V_K^{p_1,p_2}$ is compact in $(\mathcal{P}_{p}(\mathbb{R}^d),\mathcal{W}_{p_1})$ for any $p\in[p_1,p_2]$.

\label{assume:A}
The functions $b$, $\sigma$, $\sigma^0$, $f$ and $g$ are jointly continuous in $(t,x, \mu,a)\in ([0,T],|\cdot|) \times (\mathbb{R}^d,|\cdot|)\times (\mathcal{P}_{2}(\mathbb{R}^d),\mathcal{W}_1)\times  (A,|\cdot|)$. Moreover, there exist constants $K\geq 0$, $\rho \in[0,1)$ and $\beta \in (0,1]$ such that for any $a\in A$, $(t,x,\mu)$, $(t',x',\mu')\in[0,T]\times\mathbb{R}^d\times\mathcal{P}_2(\mathbb{R}^d)$, it holds that
			\begin{align*}
			{\it (1)}.\,\,&\big|b(t,x,\mu,a)-b(t',x',\mu',a)\big|+\big|\sigma(t,x,a) - \sigma(t',x',a)\big|+\big|\sigma^0(t,x)-\sigma^0(t',x')\big|\\
				&+\big|f(t,x,\mu,a)-f(t',x',\mu',a)\big|+\big|g(x,\mu) - g(x',\mu')\big|
				\leq K\big[|x-x'|+|t-t'|^\beta+\mathcal{W}_1(\mu,\mu')\big];\\[3mm]
				{\it (2)}.\,\,&\big|b(t,x,\mu,a)\big|+\big|\sigma(t,x,a)\big|+\big|\sigma^0(t,x)\big|\leq K(1+|x|^\rho);\\[3mm]
    {\it (3)}.\,\,&\big|f(t,x,\mu,a)\big|+\big|g(x,\mu)\big|\leq K.
			\end{align*}

\label{assume:B}
   For any $a \in A$, the functions $\sigma(\cdot, \cdot, a)$ and $\sigma^0(\cdot,\cdot)$ belong to $C^{1,2}\left([0, T] \times \mathbb{R}^d\right)$. Moreover, there exists a constant $K \geq 0$ such that
		\begin{align*}
			\left|\partial_t \sigma(t, x, a)\right|+\left|\nabla_x \sigma(t, x, a)\right|+\big|\nabla_{xx}^2 \sigma(t, x, a)\big|+\left|\partial_t \sigma^0(t,x)\right|+\left|\nabla_x \sigma^0(t,x)\right|+\left|\nabla_{xx}^2 \sigma^0(t,x)\right| \leq K,
		\end{align*}
		for all $(t, x, a) \in[0, T] \times \mathbb{R}^d \times A$.

The set $C^{1,2}([0,T]\times \mathcal{P}_2(\mathbb{R}^d))$ consists of all $([0,T],|\cdot|) \times (\mathcal{P}_{2}(\mathbb{R}^d),\mathcal{W}_2)$ continuous functions $\varphi:[0,T]\times \mathcal{P}_2(\mathbb{R}^d) \to \mathbb{R}$ satisfying the following:
		\begin{enumerate}[(1).]

			\item the derivatives $\partial_t \varphi(t,\mu)$, $\partial_\mu \varphi(t,\mu)(x)$, $\nabla_x \partial_\mu \varphi (t,\mu)(x)$, $\partial_\mu^2 \varphi(t,\mu)(x,x')$ exist and are jointly continuous in $(t, \mu, x, x')\in ([0,T],|\cdot|) \times (\mathcal{P}_{2}(\mathbb{R}^d),\mathcal{W}_2)\times (\mathbb{R}^d,|\cdot|)\times (\mathbb{R}^d,|\cdot|)$;
			\item there is a constant $C_\varphi\geq 0$ such that for any $(t,\mu,x,x') \in [0,T] \times \mathcal{P}_2(\mathbb{R}^d)\times \mathbb{R}^d\times \mathbb{R}^d$, we have
\begin{align*}			
     |\partial_t \varphi(t,\mu)|+\scalerel*[5pt]{\big|}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big|}}}\partial_\mu^2 \varphi(t,\mu)(x,x')\scalerel*[5pt]{\big|}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big|}}}+\scalerel*[5pt]{\big|}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big|}}}\nabla_x\partial_\mu \varphi(t,\mu)(x)\scalerel*[5pt]{\big|}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big|}}}\leq C_\varphi\quad \text{and }\quad
     \scalerel*[5pt]{\big|}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big|}}}\partial_\mu \varphi(t,\mu)(x)\scalerel*[5pt]{\big|}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big|}}}\leq C_\varphi\scalerel*[5pt]{\big(}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big(}}}1+|x|\scalerel*[5pt]{\big)}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big)}}}.
\end{align*}
		\end{enumerate}
  \label{def. of C1,2}

\label{prop. property of X}
		Suppose that Assumption \ref{assume:A} holds. For every $t\in [0,T]$, $\xi\in L^2(\Omega^1,\mathcal{F}^1_t,\mathbb{P}^1;\mathbb{R}^d)$ and $\alpha\in\mathcal{A}_t$, there exists a unique (up to $\mathbb{P}$-indistinguishability) continuous $\mathbb{F}$-progressively measurable solution $X^{t,\xi,\alpha} = (X^{t,\xi,\alpha}_s)_{s\in [t,T]}$ of equation (\ref{dynamics}). Moreover, there is a constant $C$ depending only on $K$, $T$, $d$ such that
			\begin{align*}
&\mathbb{E}\Big[\sup_{s\in[t,T]}|X_s^{t,\xi,\alpha}|^2\Big]\leq C \scalerel*[5pt]{\big(}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big(}}}1+\mathbb{E}|\xi|^2\mathclose{\scalerel*[5pt]{\big)}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big)}}}},\quad
\mathbb{E}\Big[\sup_{s\in [t,T]}|X_{s}^{t,\xi,\alpha}-X_{s}^{t,\xi',\alpha}|^2\Big]\leq C \mathbb{E}\scalerel*[5pt]{\big(}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big(}}}|\xi-\xi'|^2\mathclose{\scalerel*[5pt]{\big)}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big)}}}}\quad\text{and}\\
&\mathbb{E}\Big[\sup_{s\in[t,t+h]}|X^{t,\xi,\alpha}_s-\xi|^2\Big]\leq C h,
		\end{align*}
for any $t\in [0,T]$, $h \in [0,T-t]$, $\xi,\xi'\in L^2(\Omega^1,\mathcal{F}^1_t,\mathbb{P}^1;\mathbb{R}^d)$ and $\alpha\in\mathcal{A}_t$.

\label{property_V}
		Suppose that Assumption \ref{assume:A} holds. There exists a constant $C\geq 0$ such that for any $t,t'\in[0,T]$, $\mu$, $\mu'\in \mathcal{P}_2(\mathbb{R}^d)$,
			\begin{align}
				\label{difference_V}
				|v(t,\mu)|\leq (1+T)K\quad \text{and}\quad|v(t,\mu)-v(t',\mu')| \leq C\Big[\mathcal{W}_2(\mu,\mu')
				+|t-t'|^{1/2}\Big].
			\end{align}
			The constant $C$ depends on $d$, $K$, $T$ and independent of $t$, $t'$, $\mu$, $\mu'$.

\label{dpp_thm}  
			Suppose that Assumption \ref{assume:A} holds. The value function $v$ satisfies the dynamic programming principle: for every $t\in[0,T]$ and $\mu \in \mathcal{P}_2(\mathbb{R}^d)$, it holds that
		\begin{align*}
			v(t,\mu) = & \sup_{\alpha\in\mathcal{A}_t}\sup_{s\in[t,T]}\Bigg\{\mathbb{E}\Bigg[\int_t^s f\Big(r,X_r^{t,\xi,\alpha},\mathbb{P}^{W^0}_{X_r^{t,\xi,\alpha}},\alpha_r\Big)dr+v\scalerel*[5pt]{\big(}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big(}}}s,\mathbb{P}_{X^{t,\xi,\alpha}_s}^{W^0}\scalerel*[5pt]{\big)}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big)}}}\Bigg]\Bigg\}\\
   = & \sup_{\alpha\in\mathcal{A}_t}\inf_{s\in[t,T]}\Bigg\{\mathbb{E}\Bigg[\int_t^s f\Big(r,X_r^{t,\xi,\alpha},\mathbb{P}^{W^0}_{X_r^{t,\xi,\alpha}},\alpha_r\Big)dr+v\scalerel*[5pt]{\big(}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big(}}}s,\mathbb{P}_{X^{t,\xi,\alpha}_s}^{W^0}\scalerel*[5pt]{\big)}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big)}}}\Bigg]\Bigg\},
		\end{align*}
		for any $\xi\in L^2(\Omega^1,\mathcal{F}_t^1,\mathbb{P}^1;\mathbb{R}^d)$ such that $\mathcal{L}(\xi) = \mu$.

\label{standard_ito}
		Let $(\widetilde{b}_t)_{t\geq 0}$, $(\widetilde{\sigma}_t)_{t\geq 0}$ and $(\widetilde{\sigma}_t^0)_{t\geq 0}$ be progressively measurable processes with respect to $\mathbb{F}$, with values in $\mathbb{R}^d$, $\mathbb{R}^{d\times d}$ and $\mathbb{R}^{d\times d}$ respectively, such that for any finite horizon $T>0$, 
  \begin{align*}
      \mathbb{E}\left[\int_0^T \big(|\widetilde{b}_t|^2 + |\widetilde{\sigma}_t|^4 + |\widetilde{\sigma}^0_t|^4\big)dt\right]<\infty.
  \end{align*}
  Consider the following $\mathbb{R}^d$-valued It\^o process:
		\begin{align*}
			X_t = \xi+ \int^t_0 \widetilde{b}_s ds + \int^t_0\widetilde{\sigma}_s dW_s+\int^t_0\widetilde{\sigma}_s^0dW_s^0,\quad \text{for }t\in[0,T],
		\end{align*}
        where $\xi\in L^2(\Omega,\mathcal{F},\mathbb{P};\mathbb{R}^d)$. It holds $\mathbb{P}^0$-a.s. that for $\varphi\in C^{1,2}([0,T]\times\mathcal{P}_2(\mathbb{R}^d))$,
        \begin{align*}
			&\hspace{-10pt}\varphi(t,\mathbb{P}_{X_t}^{W^0}) \\=\,& \varphi(0,\mathbb{P}_{X_0}^{W^0})  + \int_0^t \partial_t \varphi(s,\mathbb{P}_{X_s}^{W^0})ds + \int_0^t\mathbb{E}^1\big[\partial_\mu \varphi(s,\mathbb{P}_{X_s}^{W^0})(X_s)\cdot \widetilde{b}_s\big]ds\\
   &+\int_0^t \mathbb{E}^1\big[\widetilde{\sigma}_s^{0;\top} \partial_\mu \varphi(s,\mathbb{P}_{X_s}^{W^0})(X_s)\big]\cdot dW_s^0
			+\frac{1}{2}\int_0^t\mathbb{E}^1\Big\{\operatorname{tr}\pig[\nabla_x\partial_\mu \varphi(s,\mathbb{P}_{X_s}^{W^0})(X_s)\widetilde{\sigma}_s\widetilde{\sigma}_s^\top\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}\Big\}ds\\
   &+\frac{1}{2}\int_0^t\mathbb{E}^1\Big\{\operatorname{tr}\pig[\nabla_x\partial_\mu \varphi(s,\mathbb{P}_{X_s}^{W^0})(X_s)\widetilde{\sigma}_s^0\widetilde{\sigma}_s^{0;\top}\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}\Big\}ds+\frac{1}{2}\int_0^t \mathbb{E}^1\widecheck{\mathbb{E}}^1\Big\{\operatorname{tr}\Big[\partial_\mu^2 \varphi(s,\mathbb{P}_{X_s}^{W^0})(X_s,\widecheck{X}_s)\widetilde{\sigma}_s^0\scalerel*[5pt]{\big(}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big(}}}\widecheck{\widetilde{\sigma}_s^{0}}\mathclose{\scalerel*[5pt]{\big)}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big)}}}}^\top\Big]\Big\}ds,
		\end{align*}
  where $\widecheck{\mathbb{E}}^1$ is the expectation under $(\widecheck{\Omega}^1,\widecheck{\mathcal{F}}^1,\widecheck{\mathbb{P}}^1)$ which is a copy of $(\Omega^1,\mathcal{F}^1,\mathbb{P}^1)$; and $(\widecheck{X}_t)_{t\geq 0}$, $(\widecheck{\widetilde{b}}_t)_{t\geq 0}$, $(\widecheck{\widetilde{\sigma}}_t)_{t\geq 0}$, $(\widecheck{\widetilde{\sigma}_t^0})_{t\geq 0}$ are copies of $(X_t)_{t\geq 0}$, $(\widetilde{b}_t)_{t\geq 0}$, $(\widetilde{\sigma}_t)_{t\geq 0}$, $(\widetilde{\sigma}^0_t)_{t\geq 0}$ on $(\widecheck{\Omega}^1,\widecheck{\mathcal{F}}^1,\widecheck{\mathbb{P}}^1)$.

It is standard to see that $\mathbb{E}\pig[|\check{X}^{\varepsilon,t,\check{\xi},\check{\alpha}}_s
-\check{X}^{0,t,\check{\xi},\check{\alpha}}_s|^2\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}\leq C \varepsilon^2$ for any $s\in [t,T]$ by using Assumption \ref{assume:A} and equation \eqref{eq. perturbed, mfc}. The result follows by 
\begin{align*}
\left| v_{\varepsilon}(t, \mu) - v_0(t, \mu) \right|^2 
\leq 2K^2 \mathbb{E} \left[ T\int_{t}^{T} \left| \check{X}^{\varepsilon,t,\check{\xi},\check{\alpha}}_s - \check{X}^{0,t,\check{\xi},\check{\alpha}}_s \right|^2 ds + \left| \check{X}^{\varepsilon,t,\check{\xi},\check{\alpha}}_T - \check{X}^{0,t,\check{\xi},\check{\alpha}}_T \right|^2 \right]\leq C_5^2 \varepsilon^2.
\end{align*}

\label{finite_derivative_estimate}
		Suppose that Assumptions \ref{assume:A}-\ref{assume:B} hold. There are positive constants $C_4=C_4(d,K,T)$ and $C_{n,m}$ such that the function $\overline{v}_{\varepsilon,n,m} : [0,T] \times \mathbb{R}^{dn} \longmapsto \mathbb{R}$ satisfies the following:
  \begin{enumerate}[(1).]
      \item For any $(t,\overline{x})$ in $[0,T]\times \mathbb{R}^{dn}$ and $i=1,2,\ldots,n$, we have
      \begin{align}
      \label{ineq.|D v_e,n,m|}
      |\nabla_{x^i}\overline{v}_{\varepsilon,n,m}(t,\overline{x})| \leq \dfrac{C_4}{n};
      \end{align}
      \item Denoting by $\partial_{\overline{x}_i\overline{x}_j}^2 v(t,\overline{x}) \in  \mathbb{R}$ the second-order derivative with respect to $\overline{x}_i$ and $\overline{x}_j$, it holds that 
      \begin{align}
        -C_{n,m}\leq\partial^2_{\overline{x}_i\overline{x}_j}\overline{v}_{\varepsilon,n,m}(t,\overline{x}) \leq \dfrac{C_{n,m}}{\varepsilon^2},
         \label{ineq.|D^2 v_e,n,m|}
      \end{align}
      for any $(t,\overline{x})$ in $[0,T]\times \mathbb{R}^{dn}$ and every $i,j=1,2,\ldots,dn$;
      \item The function $\overline{v}_{\varepsilon,n,m} \in C^{1,2}([0,T] \times \mathbb{R}^{dn})$ is the unique classical solution of the Bellman equation 
		\begin{equation}
			\left\{
			\begin{aligned}
				&\partial_t u(t,\overline{x})
				+\sup_{\overline{a} \in A^n}\Bigg\{\dfrac{1}{n}\sum^n_{i=1}f^i_{n,m}(t,\overline{x},a^i)
				+\dfrac{1}{2}\sum^n_{i=1}\textup{tr}\left[\Big((\sigma\sigma^\top)(t,x^i,a^i)+\sigma^0\sigma^{0;\top}(t,x^i)+\varepsilon^2I_d\Big)\nabla_{x^ix^i}^2
				u(t,\overline{x})\right]\\ 
				&\hspace{80pt}+\sum^n_{i=1}\left\langle b^i_{n,m}(t,\overline{x},a^i)
				,\nabla_{x^i}u(t,\overline{x})\right\rangle
				+\frac{1}{2}\sum_{i,j=1,i\neq j}^n\textup{tr}\Big[\sigma^0(t,x^i)\sigma^{0;\top}(t,x^j)\nabla_{x^ix^j}^2u(t,\overline{x})\Big]\Bigg\}\\
				&=0\hspace{5pt} \text{in $[0,T) \times\mathbb{R}^{dn}$};\\
				&u(T,\overline{x})
				=\dfrac{1}{n}\sum^n_{i=1}g^i_{n,m}(\overline{x})
				\hspace{5pt} \text{ in $\mathbb{R}^{dn}$},
			\end{aligned}
			\right.   
			\label{eq. bellman bar v_e,n,m}
		\end{equation}
		where $\overline{a}=(a^1,\ldots,a^n)$ with $a^i\in A $ for $i=1,2,\ldots,n$. 
  \end{enumerate}

		\label{lem. classical sol. of smooth approx.}

Suppose that Assumptions \ref{assume:A}-\ref{assume:B} hold. For every $\varepsilon > 0$,
		$n,m \in \mathbb{N}$, the function $\overline{v}_{\varepsilon,n,m}$ defined in \eqref{def. tilde v_e,n,m} and the function $v_{\varepsilon,n,m}$ defined in \eqref{def. v_e=V_e mfg} satisfy the following:
		\begin{enumerate}[(1).]
			\item 
			For any $(t,\mu) \in [0,T] \times \mathcal{P}_2(\mathbb{R}^d)$, we have
			\begin{align}
				v_{\varepsilon,n,m}(t,\mu)
				=\int_{\mathbb{R}^{dn}}
				\overline{v}_{\varepsilon,n,m}
				(t,x^1,\ldots,x^n)
				\mu(dx^1)\otimes\ldots\otimes\mu(dx^n)\, ;
				\label{eq. v_e,n,m=int bar of v_e,n,m}
			\end{align}
			\item  $v_{\varepsilon,n,m}(t,\mu) \in C^{1,2}([0,T] \times \mathcal{P}_2(\mathbb{R}^d))$;
			\item There is a positive constant $\ell_2=\ell_2(K,T)$ such that for any $(t,\mu) \in [0,T] \times \mathcal{P}_2(\mathbb{R}^d)$, we have $|v_{\varepsilon,n,m}(t,\mu)|\leq \ell_2$;
			\item The function $v_{\varepsilon,n,m}(t,\mu)$ solves the following equation in the classical sense:
			\begin{equation*}
				\left\{
				\begin{aligned}
					&\partial_t u(t,\mu)\\
					&+\int_{\mathbb{R}^{dn}}
					\sup_{\overline{a} \in A^n}\Bigg\{\dfrac{1}{n}\sum^n_{i=1}f^i_{n,m}(t,\overline{x},a^i)
     +\sum^n_{i=1}\left\langle b^i_{n,m}(t,\overline{x},a^i),\nabla_{x^i}\overline{v}_{\varepsilon,n,m}(t,\overline{x})\right\rangle
					\\
					&\hspace{65pt}
     +\dfrac{1}{2}
			\sum^n_{i=1}\textup{tr}\left[\Big((\sigma\sigma^\top)(t,x^i,a^i)
					+(\sigma^0\sigma^{0;\top})(t,x^i)+\varepsilon^2I_d\Big)\nabla_{x^ix^i}^2
					\overline{v}_{\varepsilon,n,m}
	(t,\overline{x})\right]\\
 		&\hspace{65pt}+\frac{1}{2}\sum_{i,j=1,i\neq j}^n\textup{tr}\Big[\sigma^0(t,x^i)\sigma^{0;\top}(t,x^j)\nabla_{x^ix^j}^2\overline{v}_{\varepsilon,n,m}(t,\overline{x})\Big]\Bigg\}\mu(dx^1)\otimes\ldots\otimes \mu(dx^n)\\
					&=0\hspace{5pt} \text{for any $(t,\mu) \in [0,T) \times\mathcal{P}_2(\mathbb{R}^{d})$};\\
					& u(T,\mu)
					=\dfrac{1}{n}\sum^n_{i=1}\int_{\mathbb{R}^{dn}}g^i_{n,m}(\overline{x})\mu(dx^1)\otimes\ldots\otimes\mu(dx^n)
					\hspace{5pt} \text{for any $\mu \in \mathcal{P}_2(\mathbb{R}^{d})$}.
				\end{aligned}
				\right.    
			\end{equation*}
		\end{enumerate}
		\label{thm v_e,n,m}

Let $\mu$, $\mu' \in \mathcal{P}_2(\mathbb{R}^d)$. Let $(\xi^1,\eta^1),\ldots,(\xi^n,\eta^n)$ be a sequence of independent and identically distributed random variables, with $\mathcal{L}(\xi^i) = \mu$, $\mathcal{L}(\eta^i) = \mu'$, for $i = 1,\ldots, n$. Theorem \ref{thm v_e,n,m} deduces that $v_{\varepsilon,n,m}(t,\mu) = \mathbb{E}\bar{v}_{\varepsilon,n,m}(t,\xi^1,\ldots,\xi^n)$ and $v_{\varepsilon,n,m}(t,\mu') = \mathbb{E}\bar{v}_{\varepsilon,n,m}(t,\eta^1,\ldots,\eta^n)$. Lemma \ref{lem. classical sol. of smooth approx.} implies that
            \begin{align*}
                |v_{\varepsilon,n,m}(t,\mu)-v_{\varepsilon,n,m}(t,\mu')|
                \leq \mathbb{E}|\bar{v}_{\varepsilon,n,m}(t,\xi^1,\ldots,\xi^n) - \bar{v}_{\varepsilon,n,m}(t,\eta^1,\ldots,\eta^n)|
                \leq &\frac{C_4}{n}\sum_{i=1}^n\mathbb{E}|\xi^i - \eta^i|\\
                =&C_4\mathbb{E}|\xi^1 - \eta^1|.
            \end{align*}
            Since $\xi^1$ and $\eta^1$ are arbitrary random variables such that $\mathcal{L}(\xi^1) = \mu$ and $\mathcal{L}(\eta^1) = \mu'$, we conclude that 
            \begin{align*}
                |v_{\varepsilon,n,m}(t,\mu)-v_{\varepsilon,n,m}(t,\mu')|\leq C_4\mathcal{W}_1(\mu,\mu').
            \end{align*}
            Now we consider $v$. Let $\mathcal{L}(\xi) = \mu$ and $\mathcal{L}(\eta) = \mu'$. By applying Proposition \ref{property_V}, together with Lemmas \ref{lem. |v_e,n,m-v_0,n,m| < C_6e} and \ref{lem. conv. of v_e,n,m to v_e}, we have
        \begin{align*}
                |v(t,\mu) - v(t,\mu')| =& |V(t,\xi) - V(t,\eta)|\\
                =& \lim_{k\to\infty} |V(t,\xi \mathds{1}_{\{|\xi|\leq k\}}) - V(t,\eta \mathds{1}_{\{|\eta|\leq k\}})|\\
                = &\lim_{k\to\infty} \lim_{\varepsilon\to0}\lim_{n\to\infty}\lim_{m\to\infty}|v_{\varepsilon,n,m}(t,\mathcal{L}(\xi \mathds{1}_{\{|\xi|\leq k\}})) - v_{\varepsilon,n,m}(t,\mathcal{L}(\eta \mathds{1}_{\{|\eta|\leq k\}}))|\\
                \leq &\,C_4\lim_{k\to\infty} \mathbb{E}|\xi \mathds{1}_{\{|\xi|\leq k\}} - \eta \mathds{1}_{\{|\eta|\leq k\}}|\\
                =&\,C_4 \mathbb{E}|\xi - \eta|.
            \end{align*}
            As $\xi$, $\eta$ are arbitrary, provided that $\mathcal{L}(\xi) = \mu$ and  $\mathcal{L}(\eta) = \mu'$, we conclude that $|v(t,\mu) - v(t,\mu')|\leq C_4\mathcal{W}_1(\mu,\mu')$.

\label{existence_label}
