    &+\frac{\sqrt{3}K}{h}\sqrt{\mathbb{E}\mathbb{E}^1|\partial_\mu \varphi(t_0,\mu_0)(\xi)|^2}\int_{t_0}^{t_0+h} \sqrt{\mathbb{E}\mathbb{E}^1\Big(|s-t_0|^{2\beta} + |X_s^{t_0,\xi,\alpha^\varepsilon}-\xi|^2+\pig[\mathcal{W}_1(\mathbb{P}^{W^0}_{X_s^{t_0,\xi,\alpha^\varepsilon}},\mu_0)\mathclose{\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}}^2\Big)}ds.\nonumber
\end{align}
The convergence of the term in \eqref{1314} is due to the continuity as proved in \eqref{continuity_measure_flow}, Proposition \ref{prop. property of X}, the regularity of the test function $\varphi$ and the dominated convergence theorem. Thus, the term II converges to zero as $h \to 0^+$ with the aid of Proposition \ref{prop. property of X}. Similar estimate holds for the term $ 
  \textup{\uppercase\expandafter{\romannumeral3}} 
$, thus putting \eqref{767} and \eqref{782} into \eqref{759} and then passing $h\to 0^+$, we obtain that 
\begin{align*}
			0\leq \,&\partial_t\varphi(t_0,\mu_0)+\mathbb{E}\sup_{a\in A}\bigg\{f(t_0,\xi,\mu_0,a) + \big[\partial_\mu \varphi(t_0,\mu_0)(\xi)\cdot b(t_0,\xi,a,\mu_0)\big]\\
			&+\frac{1}{2}\operatorname{tr}\pig[\nabla_x\partial_\mu \varphi(t_0,\mu_0)(\xi)\sigma(t_0,\xi,a)\sigma^\top(t_0,\xi,a)\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}\bigg\}+\mathbb{E}\widecheck{\mathbb{E}}\Bigg\{\frac{1}{2}\operatorname{tr}\Big[\nabla_x\partial_\mu \varphi(t_0,\mu_0)(\xi)\sigma^0(t_0,\xi)[\sigma^0(t_0,\xi)]^\top\Big]\\&+\frac{1}{2}\operatorname{tr} \pig[\partial_\mu^2 \varphi(t_0,\mu_0)(\xi,\widecheck{\xi})
   \sigma^0(t_0,\xi)[\sigma^0(t_0,\widecheck{\xi})]^\top\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}\Bigg\}+\varepsilon. 
		\end{align*}
  As $\varepsilon>0$ is arbitrary, the claim is proved.

\label{thm:main}
		Suppose that Assumptions \ref{assume:A}-\ref{assume:B} hold. Let  $u_1$, $u_2 : [0,T]\times \mathcal{P}_2(\mathbb{R}^d) \to \mathbb{R}$ be the viscosity subsolution and supersolution (in the sense of Definition \ref{def. of vis sol}) of equation \eqref{HJB_intro} respectively. Then it holds that $u_1 \leq u_2$ on $[0,T]\times \mathcal{P}_2(\mathbb{R}^d)$. Hence, the viscosity solution of equation \eqref{HJB_intro} is unique.
		\label{thm compar}

Recalling the function $v_0$ defined in \eqref{def. v_e=V_e mfc} with $\varepsilon=0$, we shall prove that $u_1\leq v_{0}$ and $v_{0} \leq u_2$ on $[0,T]\times \mathcal{P}_2(\mathbb{R}^d)$. We prove the cases for subsolution and supersolution separately.

\medskip

\noindent {\bf Part 1. Proof of  $u_1\leq v_{0}$:} Let $u_1$ be a bounded viscosity subsolution of the equation \eqref{HJB_intro}. To prove $u_1\leq v_{0}$ by contradiction, we assume  that there exists $(t_0,\widetilde{\mu}_0)\in [0,T] \times \mathcal{P}_2(\mathbb{R}^d)$ such that
		\begin{align*}
			(u_1-v_{0})(t_0,\widetilde{\mu}_0) >0.
		\end{align*}
		Let $\xi\in L^2(\Omega,\mathcal{F},\mathbb{P};\mathbb{R}^d)$ such that $\mathcal{L}(\xi)=\widetilde{\mu}_0$. For any $k\in \mathbb{N}$, we let $\mu_0^k \in \mathcal{P}_2(\mathbb{R}^d)$ be the law of $\xi\mathds{1}_{\{|\xi|\leq k\}}$. We see that $\mu_0^k \in \mathcal{P}_q(\mathbb{R}^d)$ for any $q\geq1$ and
		$$ \pig[\mathcal{W}_1(\mu_0^k,\widetilde{\mu}_0)\mathclose{\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}}^2\leq\pig[\mathcal{W}_2(\mu_0^k,\widetilde{\mu}_0)\mathclose{\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}}^2\leq \mathbb{E}\pig[|\xi\mathds{1}_{\{|\xi|\leq k\}}-\xi|^2\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}} =\int_{|x|>k}|x|^2\widetilde{\mu}_0(dx) \longrightarrow 0$$
		as $k \to \infty$. Therefore, as both $u_1$ and $v_{0}$ are continuous on $[0,T] \times \mathcal{P}_2(\mathbb{R}^d)$, we can find a $k \in \mathbb{N}$ large enough such that $\mu_0 := \mu_0^k\in \mathcal{P}_q(\mathbb{R}^d)$ for any $q\geq1$ and 
		\begin{align}
			(u_1-v_{0})(t_0, \mu_0) >0.
			\label{ineq. u_1-v_0(t_0,mu_0)>0}
		\end{align}
  	 \noindent {\bf Step 1A: Construction of the comparison function:} Recalling the approximations defined in \eqref{def. approx of f}, \eqref{def. approx of g}, \eqref{def. tilde v_e,n,m} and \eqref{eq. v_e,n,m=int bar of v_e,n,m}, we define $\widecheck{u}_1(t,x):=e^{t-t_0}u_1(t,x)$ and similarly for $\widecheck{\overline{v}}_{\varepsilon,n,m}$, $\widecheck{v}_{\varepsilon,n,m}$, $\widecheck{f}^i_{n,m}$, $\widecheck{f}$ from $\overline{v}_{\varepsilon,n,m}$, $v_{\varepsilon,n,m}$, $f^i_{n,m}$, $f$ respectively. We also define $\widecheck{g}:=e^{T-t_0}g$ and $\widecheck{g}^i_{n,m}:=e^{T-t_0}g^i_{n,m}$.  By direct computation, we see that $\widecheck{u}_1$ is a viscosity subsolution of the equation
  \begin{equation}\label{eq. vis subsol of check u1}
			\left\{\begin{aligned}
				&\partial_t u(t,\mu)
				+\int_{\mathbb{R}^d}
				\sup_{a\in A} \Bigg\{\widecheck{f}(t,x,\mu,a)+b(t,x,\mu,a)\cdot \partial_\mu u(t,\mu)(x) \\
				&\hspace{90pt}+ \dfrac{1}{2}\text{tr}\Big[\scalerel*[5pt]{\big(}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big(}}}\sigma(t,x,a)\big[\sigma(t,x,a)\big]^\top+\sigma^0(t,x)[\sigma^0(t,x)]^\top\scalerel*[5pt]{\big)}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big)}}}\nabla_x\partial_\mu u(t,\mu)(x)\Big]\Bigg\}\mu(dx) \\
				&+ \dfrac{1}{2} \int_{\mathbb{R}^{2d}}\text{tr}\Big[\sigma^0(t,x)[\sigma^0(t,y)]^\top\partial_\mu^2
    u(t,\mu)(x,y)\Big] \, \mu^{\otimes 2}(dx,dy)-u(t,\mu)\\
    &=0\hspace{5pt} \text{for $(t,\mu) \in [0,T) \times\mathcal{P}_2(\mathbb{R}^d)$};\\
				&u(T,\mu)=\int_{\mathbb{R}^d}\widecheck{g}(x,\mu)\mu(dx) \hspace{10pt}\text{for $\mu\in \mathcal{P}_2(\mathbb{R}^d)$},
			\end{aligned}\right.
		\end{equation}
in the sense of Definition \ref{def. of vis sol}. By Theorem \ref{thm v_e,n,m}, we obtain that $\widecheck{v}_{\varepsilon,n,m}$ solves the following equation in the classical sense:
		\begin{equation}
			\left\{
			\begin{aligned}
				&\partial_t u(t,\mu)+\int_{\mathbb{R}^{dn}}
				\sup_{\overline{a} \in A^n}\Bigg\{\dfrac{1}{n}\sum^n_{i=1}\widecheck{f}^i_{n,m}(t,\overline{x},a^i)
    +\sum^n_{i=1}\Big\langle b^i_{n,m}(t,\overline{x},a^i)
				,\nabla_{x^i}\widecheck{\overline{v}}_{\varepsilon,n,m}(t,\overline{x})\Big\rangle\\
				&\hspace{100pt}+\dfrac{1}{2}
				\sum^n_{i=1}\textup{tr}\left[\Big((\sigma\sigma^\top)(t,x^i,a^i)+(\sigma^0\sigma^{0;\top})(t,x^i)+\varepsilon^2I_d\Big)\nabla_{x^ix^i}^2
				\widecheck{\overline{v}}_{\varepsilon,n,m}
				(t,\overline{x})\right]\\
				&\hspace{100pt}+\dfrac{1}{2}
				\sum^n_{i,j=1,i\neq j}\textup{tr}\left[\sigma^0(t,x^i)\sigma^{0;\top}(t,x^j)\nabla_{x^ix^j}^2
				\widecheck{\overline{v}}_{\varepsilon,n,m}
		(t,\overline{x})\right]\Bigg\}\operatorname*{\text{\raisebox{0.25ex}{\scalebox{0.75}{$\bigotimes$}}}}_{k=1}^n\mu(dx^k)
				-u (t,\mu)\\
				&=0\hspace{5pt} \text{for $(t,\mu) \in [0,T) \times\mathcal{P}_2(\mathbb{R}^{d})$};\\
				& u(T,\mu)
				=\dfrac{1}{n}\sum^n_{i=1}\int_{\mathbb{R}^{dn}}\widecheck{g}^i_{n,m}(\overline{x})\operatorname*{\text{\raisebox{0.25ex}{\scalebox{0.75}{$\bigotimes$}}}}_{k=1}^n\mu(dx^k)
				\hspace{5pt} \text{for $\mu \in \mathcal{P}_2(\mathbb{R}^{d})$},
			\end{aligned}
			\right.    
			\label{eq. vis sol of check v_e,n,m}
		\end{equation}
		where we write 	$\displaystyle\operatorname*{\text{\raisebox{0.25ex}{\scalebox{0.75}{$\bigotimes$}}}}_{k=1}^n\mu(dx^k):=\mu(dx^1)\otimes\ldots\otimes\mu(dx^n)$ and $\overline{a}=(a^1,\ldots,a^n)$ for each $a^i \in A$ with $i=1,2,\ldots,n$.

Let $l_0:=(u_1-v_{0})(t_0, \mu_0)>0$. Referring to \eqref{moment_V_def} for the definition of $M_{2}(\mu_0)$, we choose a sufficiently small $\delta>0$, depending on $M_{2}(\mu_0)$ and $l_0$ only, such that $u_1(t_0,\mu_0)- v_0(t_0,\mu_0)-\delta M_{2}(\mu_0)\geq l_0/2$ and thus $u_1(t_0,\mu_0)- v_{\varepsilon, n,m}(t_0,\mu_0)-\delta M_{2}(\mu_0)\geq l_0/3$, for small enough $\varepsilon>0$ and large enough $n$, $m\in \mathbb{N}$ depending on $l_0$, by Lemmas \ref{lem. |v_e-v_0|<C_5 e} and \ref{lem. conv. of v_e,n,m to v_e}. Thus, it holds that 
\begin{equation}\label{eq:cpt}
\displaystyle\sup_{(t,\mu)\in [0,T] \times \mathcal{P}_2(\mathbb{R}^d)} \widecheck{u}_1(t,\mu)- \widecheck{v}_{\varepsilon, n,m}(t,\mu)-\delta M_{2}(\mu)\geq l_0/3,
\end{equation}
for small enough $\varepsilon>0$ and large enough $n$, $m\in \mathbb{N}$ depending on $l_0$. Define the set 
\begin{align*}
U^2_{\delta,\varepsilon, n,m}:=\scalerel*[5pt]{\big\{}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big\{}}}(t,\mu) \in [0,T]\times\mathcal{P}_2(\mathbb{R}^d):\widecheck{u}_1(t,\mu)- \widecheck{v}_{\varepsilon, n,m}(t,\mu)-\delta M_{2}(\mu)\geq l_0/3\scalerel*[5pt]{\big\}}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big\}}}},
\end{align*}
which is non-empty as $u_1(t_0,\mu_0)- v_{\varepsilon, n,m}(t_0,\mu_0)-\delta M_{2}(\mu_0)\geq l_0/3$. It is obvious that
\begin{align*}
    \displaystyle\sup_{(t,\mu)\in [0,T] \times \mathcal{P}_2(\mathbb{R}^d)} \widecheck{u}_1(t,\mu)- \widecheck{v}_{\varepsilon, n,m}(t,\mu)-\delta M_{2}(\mu)
    =\displaystyle\sup_{(t,\mu)\in U^2_{\delta,\varepsilon, n,m}} \widecheck{u}_1(t,\mu)- \widecheck{v}_{\epsilon, n,m}(t,\mu)-\delta M_{2}(\mu).
\end{align*}
Since $\widecheck{u}_1$ and $\widecheck{v}_{\varepsilon,n,m}$ are bounded independent of $\varepsilon,n,m$ by Theorem \ref{thm v_e,n,m}, it yields that for any $\mu \in U^2_{\delta,\varepsilon, n,m}$,
\begin{align}
\label{bound_V}
\delta M_2(\mu)
\leq l_0/3+e^T\lVert u_1\rVert_{\infty} + e^T\lVert v_{\varepsilon,n,m} \rVert_{\infty}
\leq l_0/3+e^T(\lVert u_1\rVert_{\infty} +\ell_2)
< +\infty,
\end{align}
where $\ell_2$ is the constant given in Theorem \ref{thm v_e,n,m}. Then we see that
\begin{align*}
U^2_{\delta,\varepsilon, n,m}\subset\Big\{(t,\mu) \in [0,T]\times\mathcal{P}_2(\mathbb{R}^d):
M_{2}(\mu)\leq \dfrac{1}{\delta}\pig[l_0/3+e^T(\lVert u_1\rVert_{\infty} +\ell_2)\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}\Big\}=:U^2_\delta.
\end{align*}
The set $U^2_\delta$ is compact in $\big([0,T],|\cdot|\big) \times (\mathcal{P}_{2}(\mathbb{R}^d),\mathcal{W}_1)$ due to Lemma \ref{lem. compact of V^p_K}. Note that $\widecheck{u}_1(t,\mu)$ is $\big([0,T],|\cdot|\big) \times (\mathcal{P}_{2}(\mathbb{R}^d),\mathcal{W}_1)$-continuous by our definition of viscosity solution, $\widecheck{v}_{\varepsilon, n,m}(t,\mu)$ is $\big([0,T],|\cdot|\big) \times (\mathcal{P}_{2}(\mathbb{R}^d),\mathcal{W}_1)$-continuous by Lemma \ref{v_W1_continuous}, and $-\delta M_2(\mu)$ is $\mathcal{W}_1$-upper semicontinuous from Remark \ref{V_lower_semi}, therefore $\widecheck{u}_1-\widecheck{v}_{\varepsilon,n,m}-\delta M_2$ is upper semicontinuous in $\big([0,T],|\cdot|\big) \times (\mathcal{P}_{2}(\mathbb{R}^d),\mathcal{W}_1)$. It implies that the set $U^2_{\delta,\varepsilon, n,m}$ is a closed subset of $U^2_\delta$ under $\big([0,T],|\cdot|\big) \times (\mathcal{P}_{2}(\mathbb{R}^d),\mathcal{W}_1)$. Therefore, $U^2_{\delta,\varepsilon, n,m}$ is compact in $\big([0,T],|\cdot|\big) \times (\mathcal{P}_{2}(\mathbb{R}^d),\mathcal{W}_1)$. The same arguments imply that  $U^2_{\delta,\varepsilon, n,m}$ is compact in $\big([0,T],|\cdot|\big) \times (\mathcal{P}_{1}(\mathbb{R}^d),\mathcal{W}_1)$ as well. Let $\{(t_k,\mu_k)\}_{k\in\mathbb{N}}$ be a sequence in $U^2_{\delta,\varepsilon, n,m}$ such that 
\begin{align}
\label{about_to_limsup}
    \widecheck{u}_1(t_k,\mu_k)- \widecheck{v}_{\varepsilon, n,m}(t_k,\mu_k)-\delta M_{2}(\mu_k)>\displaystyle\sup_{(t,\mu)\in U^2_{\delta,\epsilon, n,m}} \widecheck{u}_1(t,\mu)- \widecheck{v}_{\varepsilon, n,m}(t,\mu)-\delta M_{2}(\mu)-\frac{1}{k}.
\end{align}
By the compactness of $U^2_{\delta,\varepsilon, n,m}$ and the upper semicontinuity of $\widecheck{u}_1-\widecheck{v}_{\varepsilon,n,m}-\delta M_2$, there exists $(\widetilde{t},\widetilde{\mu}) \in [0,T] \times U^2_{\delta,\varepsilon, n,m}$ such that $(t_k,\mu_k)\to(\widetilde{t},\widetilde{\mu})$ in $\big([0,T],|\cdot|\big) \times (\mathcal{P}_{2}(\mathbb{R}^d),\mathcal{W}_1)$. From \eqref{about_to_limsup}, we conclude that 
\begin{align*}
    \widecheck{u}_1(\widetilde{t},\widetilde{\mu})- \widecheck{v}_{\varepsilon, n,m}(\widetilde{t},\widetilde{\mu})-\delta M_{2}(\widetilde{\mu})\geq& \limsup_k \pig[\widecheck{u}_1(t_k,\mu_k)- \widecheck{v}_{\varepsilon, n,m}(t_k,\mu_k)-\delta M_{2}(\mu_k)\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}\\
    \geq&\sup_{(t,\mu)\in U^2_{\delta,\varepsilon, n,m}} \widecheck{u}_1(t,\mu)- \widecheck{v}_{\varepsilon, n,m}(t,\mu)-\delta M_{2}(\mu),
\end{align*}
and the maximum is attained at $(\widetilde{t},\widetilde{\mu})$. We note that this maximum point depends on $\delta,\varepsilon, n,m$.\\
\hfill\\
 \noindent{\bf Step 1B. Proof of $\widetilde{t}<T$:} In this step, we aim to prove that $\widetilde{t}<T$. Suppose, on the contrary, that  $\widetilde{t}=T$. The definition of the point $(\widetilde{t},\widetilde{\mu})=(T,\widetilde{\mu})$ implies that $u_1(t_0,\mu_0) - v_{\varepsilon,n,m}(t_0,\mu_0)-\delta M_{2}(\mu_0)\leq  \widecheck{u}_1(T,\widetilde{\mu}) - \widecheck{v}_{\varepsilon,n,m}(T,\widetilde{\mu})-\delta M_{2}(\widetilde{\mu})\leq  \widecheck{u}_1(T,\widetilde{\mu}) - \widecheck{v}_{\varepsilon,n,m}(T,\widetilde{\mu})$. Thus, for $\widehat{\mu}^{n,\overline{x}}:=\dfrac{1}{n}\displaystyle\sum^n_{j=1} \delta_{x^j}$, we can use the terminal conditions in equations \eqref{eq. vis subsol of check u1} and \eqref{eq. vis sol of check v_e,n,m} to obtain that 
		\begin{align*}
			&\hspace{-10pt}u_1(t_0,\mu_0) - v_{\varepsilon,n,m}(t_0,\mu_0)\\
			\leq\,& \dfrac{e^{T-t_0}}{n}
			\sum^n_{i=1}\left[
			\int_{\mathbb{R}^{dn}}
			\left(g(x^i,\widetilde{\mu})
			-g^i_{n,m}(x^1,\ldots,x^n)\right)
			\operatorname*{\text{\raisebox{0.25ex}{\scalebox{0.75}{$\bigotimes$}}}}_{k=1}^n\widetilde{\mu}(dx^k)
			\right]+\delta M_{2}(\mu_0)\\
			=\,& \dfrac{e^{T-t_0}}{n}
			\sum^n_{i=1}\left[
			\int_{\mathbb{R}^{dn}}
			\left(g(x^i,\widetilde{\mu})
			-g(x^i,\widehat{\mu}^{n,\overline{x}})\right)
			\operatorname*{\text{\raisebox{0.25ex}{\scalebox{0.75}{$\bigotimes$}}}}_{k=1}^n\widetilde{\mu}(dx^k)
			\right]\\
			&+\dfrac{e^{T-t_0}}{n}
			\sum^n_{i=1}\left[
			\int_{\mathbb{R}^{dn}}
			\left(g(x^i,\widehat{\mu}^{n,\overline{x}})
			-g^i_{n,m}(x^1,\ldots,x^n)\right)
			\operatorname*{\text{\raisebox{0.25ex}{\scalebox{0.75}{$\bigotimes$}}}}_{k=1}^n\widetilde{\mu}(dx^k)
			\right]
   +\delta M_{2}(\mu_0).
		\end{align*}
		Using the Lipschitz property of $g$ in Assumption \ref{assume:A} and (2) of Lemma \ref{lem estimate of b^i_n,m...}, we further have
		\begin{align}
			&\hspace{-10pt}u_1(t_0,\mu_0) - v_{\varepsilon,n,m}(t_0,\mu_0)\nonumber\\
			\leq\,&Ke^{T-t_0}
			\left[
			\int_{\mathbb{R}^{dn}}
			\mathcal{W}_1(\widetilde{\mu},\widehat{\mu}^{n,\overline{x}})
			\operatorname*{\text{\raisebox{0.25ex}{\scalebox{0.75}{$\bigotimes$}}}}_{k=1}^n\widetilde{\mu}(dx^k)
			\right]+\dfrac{2Ke^{T-t_0}}{n}
			\left[
			m^{dn}\int_{\mathbb{R}^{dn}}
			\left(\sum^n_{i=1}|y^i|\right) \prod^n_{j=1}\Phi(my^j)dy^j
			\right]\nonumber\\
   &+\delta M_{2}(\mu_0).
			\label{1139}
		\end{align}
  From \cite[Theorem 1]{FG15}, there is a constant $C_d>0$ depending on $d$ only and a sequence $\{h_n\}_{n \in \mathbb{N}} \subset \mathbb{R}$ such that 
  \begin{align}
			\int_{\mathbb{R}^{dn}}
			\mathcal{W}_1(\widetilde{\mu},\widehat{\mu}^{n,\overline{x}})
			\operatorname*{\text{\raisebox{0.25ex}{\scalebox{0.75}{$\bigotimes$}}}}_{k=1}^n\widetilde{\mu}(dx^k)
			\leq C_{d} h_n\left[\int_{\mathbb{R}^{d}}|x|^{q_0}\widetilde{\mu}(dx)\right]^{1/q_0}.
   \label{def. h_n}
		\end{align}
The sequence $\{h_n\}_{n \in \mathbb{N}}$ and the number $q_0$ are given by
  \[
h_n=
\left\{
\begin{array}{ll}
n^{-1/2} + n^{-(q_0-1)/q_0} & \text{if } d=1; \\
n^{-1/2} \log(1+n) + n^{-(q_0-1)/q_0} & \text{if }  d=2; \\
n^{-1/d} + n^{-(q_0-1)/q_0} & \text{if } d>2,
\end{array}
\right.
\quad \text{with}\quad
q_0=
\left\{
\begin{array}{ll}
3/2 & \text{if } d=1,2; \\
5/3 & \text{if } d>2,
\end{array}
\right.
\]
where $h_n$ satisfies $\lim_{n\to \infty}h_n=0$. Inequalities \eqref{bound_V} and \eqref{def. h_n} further imply
		\begin{align}
			\dfrac{1}{C_dh_n}\int_{\mathbb{R}^{dn}}
			\mathcal{W}_1(\widetilde{\mu},\widehat{\mu}^{n,\overline{x}})
			\operatorname*{\text{\raisebox{0.25ex}{\scalebox{0.75}{$\bigotimes$}}}}_{k=1}^n\widetilde{\mu}(dx^k)
			\leq
			\left[\int_{\mathbb{R}^{d}}
			|x|^2
			\widetilde{\mu}(dx)\right]^{1/2} 
   \leq\dfrac{1}{\delta^{1/2}}\pig[ l_0/3+e^T(\lVert u_1\rVert_{\infty} +\ell_2)\mathclose{\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}}^{1/2}.
			\label{ineq. int W_2(tilde mu- hat mu^n,x)}
		\end{align}
		Hence, from \eqref{1139} and \eqref{ineq. int W_2(tilde mu- hat mu^n,x)}, we have,
		\begin{align*}
			&\hspace{-10pt}u_1(t_0,\mu_0) - v_{\varepsilon,n,m}(t_0,\mu_0)\\
   \leq\,& \dfrac{K C_dh_ne^{T-t_0}}{\delta^{1/2}}\pig[ l_0/3+e^T(\lVert u_1\rVert_{\infty} +\ell_2)\mathclose{\scalerel*[5pt]{\big]}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big]}}}}^{1/2}
	+\dfrac{2Ke^{T-t_0}m^{dn}}{n}
			\left[
			\int_{\mathbb{R}^{dn}}
			\left(\sum^n_{i=1}|y^i|\right) \prod^n_{j=1}\Phi(my^j)dy^j
			\right]\\
   &+\delta M_{2}(\mu_0).
		\end{align*}
		Passing $m \to \infty$ and then $n \to \infty$ subsequently, we use the fact that $h_n \to 0$ to yield that 
		\begin{align*}
			u_1(t_0,\mu_0) - \lim_{n \to \infty}\lim_{m \to \infty} v_{\varepsilon,n,m}(t_0,\mu_0)
			\leq \delta M_{2}(\mu_0).
		\end{align*}
		Finally, using Lemmas \ref{lem. |v_e-v_0|<C_5 e} and \ref{lem. conv. of v_e,n,m to v_e}, we pass $\varepsilon \to 0^+$ then $\delta\to 0^+$ to conclude that $u_1(t_0,\mu_0)-v_0(t_0,\mu_0)\leq 0$, which contradicts \eqref{ineq. u_1-v_0(t_0,mu_0)>0} and thus $\widetilde{t}<T$.\\
  \hfill\\
   \noindent{\bf Step 1C. Estimate of  $u_1-v_{\varepsilon,n,m}$:}  We assume the maximum value of $\widecheck{u}_1(t,\mu)- \widecheck{v}_{\varepsilon, n,m}(t,\mu)-\delta M_{2}(\mu)$ attained at $(\widetilde{t},\widetilde{\mu})$ over $[0,T]\times \mathcal{P}_2(\mathbb{R}^d)$ is $M^* \in \mathbb{R}$. As $\widecheck{v}_{\varepsilon, n,m}(t,\mu)+\delta M_{2}(\mu) \in C^{1,2}([0,T]\times \mathcal{P}_2(\mathbb{R}^d))$, we use the fact that $\widecheck{u}_1$ is the viscosity subsolution of \eqref{eq. vis subsol of check u1} to see that
\begin{align*}
			0\leq\,&\partial_t (\widecheck{v}_{\varepsilon,n,m}+\delta  M_2) (\widetilde{t},\widetilde{\mu})
			-(\widecheck{v}_{\varepsilon,n,m}+\delta  M_2) (\widetilde{t},\widetilde{\mu})-M^*\\
