 \noindent{\bf Part 2. Proof of  $u_2\geq v_{0}$:} Following the arguments of the first part of Step II of the proof of \cite[Theorem 5.1]{cosso_master_2022},  we can assume without loss of generality that $u_2(s,\cdot)$ is $\mathcal{W}_1$-Lipschitz continuous for every $s\in [0,T]$; and showing $u_2 \geq v_0$ is equivalent to showing 
\begin{equation}
    u_2(t, \mu) \geq v^s(t, \nu):= \mathbb{E} \left[ \int_t^s f \left( r, X_r^{t, \xi, \mathfrak{a}}, \mathbb{P}_{X_r^{t, \xi, \mathfrak{a}}}^{W^0}, \mathfrak{a} \right) dr \right] + \mathbb{E}u_2 \left( s, \mathbb{P}_{X_s^{t, \xi, \mathfrak{a}}}^{W^0} \right),
    \label{1446}
\end{equation}
for every $(t, \mu) \in [0, T] \times \mathcal{P}_2(\mathbb{R}^d)$, $s \in (t, T]$, $\xi \in L^2(\Omega, \mathcal{F}_t, \mathbb{P}; \mathbb{R}^d)$ with $\mathcal{L}(\xi) = \mu$, and $\mathfrak{a} \in \mathcal{M}_t$, where $\mathcal{M}_t$ denotes the set of $\mathcal{F}_t^t$-measurable random variables $\alpha: \Omega \to A$ and $\nu:=\mathcal{L}(\xi,\mathfrak{a})$. Suppose, for contradiction, that \eqref{1446} does not hold. Then, there exist $t_0 \in [0, T)$, $s_0 \in (t_0, T]$, $\mu_0 \in \mathcal{P}_2(\mathbb{R}^d)$ and $\nu_0 \in \mathcal{P}_2(\mathbb{R}^d \times A)$, with $\mu_0$ being the marginal of $\nu_0$ on $\mathbb{R}^d$, such that
\begin{align}
v^{s_0}(t_0, \nu_0) > u_2(t_0, \mu_0).
\label{1450}
\end{align}
Following the approach outlined at the beginning of Part 1 of this proof, we assume that there exists $q > 2$ such that $\nu_0 \in \mathcal{P}_q(\mathbb{R}^d\times A)$. The function $\widecheck{u}_2(t, \mu) := e^{t-t_0} u_2(t, \mu)$ is a viscosity supersolution of the following equation:
\begin{align*}
			\left\{\begin{aligned}
				&\partial_t u(t,\mu)
				+\int_{\mathbb{R}^d}
				\sup_{a\in A} \Bigg\{\widecheck{f}(t,x,\mu,a)+b(t,x,\mu,a)\cdot \partial_\mu u(t,\mu)(x) \\
				&\hspace{90pt}+ \dfrac{1}{2}\textup{tr}\Big((\sigma(t,x,a)\big[\sigma(t,x,a)\big]^\top+\sigma^0(t,x)[\sigma^0(t,x)]^\top)\nabla_x\partial_\mu u(t,\mu)(x)\Big)\Bigg\}\mu(dx)\\
				&+ \dfrac{1}{2} \int_{\mathbb{R}^{2d}}\text{tr}\Big[\sigma^0(t,x)[\sigma^0(t,y)]^\top\partial_\mu^2
    u(t,\mu)(x,y)\Big] \, \mu^{\otimes 2}(dx,dy)-u(t,\mu)=0\hspace{5pt} \text{for $(t,\mu) \in [0,T) \times\mathcal{P}_2(\mathbb{R}^{d})$};\\	&u(T,\mu)=\int_{\mathbb{R}^d}\widecheck{g}(x,\mu)\mu(dx) \hspace{10pt}\text{for $\mu\in \mathcal{P}_2(\mathbb{R}^d)$},
			\end{aligned}\right.
		\end{align*}
where $\widecheck{f}(t,x,\mu,a):=e^{t-t_0}f(t,x,\mu,a)$ and $\widecheck{g}(x,\mu):=e^{T-t_0}g(x,\mu)$. That is, for any $s_1\in (0,T]$ and $\varphi \in C^{1,2}([0,s_1]\times\mathcal{P}_2(\mathbb{R}^d\times A))$ such that $\widecheck{u}_2-\varphi$ attains a minimum with a value of $0$ at $(t^*,\nu^*) \in [0,s_1)\times \mathcal{P}_2(\mathbb{R}^d\times A)$, then the following inequality holds:
\begin{align}
    0\geq\,&\partial_t \varphi(t^*,\nu^*)+\int_{\mathbb{R}^d\times A}
				 \Bigg\{\widecheck{f}(t^*,x,\mu^*,a)+b(t^*,x,\mu^*,a)\cdot \partial_\mu \varphi(t^*,\nu^*)(x,a) \nonumber\\
				&+ \dfrac{1}{2}\textup{tr}\Big[(\sigma(t^*,x,a)\big[\sigma(t^*,x,a)\big]^\top+\sigma^0(t^*,x)[\sigma^0(t^*,x)]^\top)\nabla_x\partial_\mu \varphi(t^*,\nu^*)(x,a)\Big]\Bigg\}\nu^*(dx,da)\nonumber\\
    &+ \dfrac{1}{2} \int_{\mathbb{R}^d \times A \times \mathbb{R}^d \times A}\text{tr}\Big[\sigma^0(t^*,x)[\sigma^0(t^*,y)]^\top\partial_\mu^2
    \varphi(t^*,\nu^*)(x,a,y,\alpha)\Big] \, (\nu^*)^{\otimes 2}(dx,da,dy,d\alpha)
    -\varphi(t^*,\nu^*),
    \label{2214}
		\end{align}
  where $\mu^*$ is the marginal of $\nu^*$ on $\mathbb{R}^d$, and the operators $\partial_\mu$, $\partial_\mu^2$ are defined as in Definition \ref{vis_def}, through the projection.

  We regularize the coefficients with respect to the control variable. Let $\Psi:\mathbb{R}^d \to \mathbb{R}^+$ be a compactly supported smooth function satisfying $\int_{\mathbb{R}^{d}}\Psi(y)dy=1$. We extend \(b\) and \(f\) to the space \([0, T] \times \mathbb{R}^{d}\times\mathcal{P}_2(\mathbb{R}^d)\times \mathbb{R}^d\) by setting $b(t,x,\mu,a)=0$ and $f(t,x,\mu,a)=0$ when $a\in\mathbb{R}^d$ is not in $A$. For simplicity, we continue to denote these extensions by \(b\) and \(f\). We further define the functions \(\widetilde{b}^{\hspace{.7pt}i}_{n,m}\) and \(\widetilde{f}^{\hspace{.7pt}i}_{n,m}\) by
\[
\widetilde{b}^{\hspace{.7pt}i}_{n,m}(t, \overline{x}, a) := m^d \int_{\mathbb{R}^d} b^i_{n,m}(t, \overline{x}, a - a') \Psi(m a') \, da',
\]
\[
\widetilde{f}^{\hspace{.7pt}i}_{n,m}(t, \overline{x}, a) := m^d \int_{\mathbb{R}^d} f^i_{n,m}(t, \overline{x}, a - a') \Psi(m a') \, da',
\]
for any $n, m \in \mathbb{N}$, $i = 1,2, \ldots, n$, $\overline{x} = (x^1,x^2, \ldots, x^n) \in \mathbb{R}^{dn}$ and $(t, a) \in [0, T] \times A$. Here $b_{n,m}^i$ and $f_{n,m}^i$ are as defined in \eqref{def. approx of b} and \eqref{def. approx of f}. Recalling the compactly supported smooth function $\Phi$ defined in Section \ref{Phi_defined}, we also define 
\begin{equation*}
u_{n,m}(t, \overline{x}) := m^{dn} \int_{\mathbb{R}^{dn}} u_2 \left(t, \frac{1}{n} \sum_{j=1}^{n} \delta_{x^j - y^j} \right) \prod_{j=1}^{n} \Phi(my^j) \, dy^j.
\end{equation*} We now introduce
\begin{align}
\label{v^s_n,m}
v^{s_0}_{n,m}(t, \nu) :=& \frac{1}{n} \sum_{i=1}^{n} \mathbb{E} \bigg[ \int_{t}^{s_0} \widetilde{f}^{\hspace{.7pt}i}_{n,m} \left( r, \overline{\widetilde{X}}^{1,m,t,\overline{\xi},\overline{\mathfrak{a}}_0}_{r}, \ldots, \overline{\widetilde{X}}^{n,m,t,\overline{\xi},\overline{\mathfrak{a}}_0}_{r}, \mathfrak{a}_0^i \right) dr\nonumber\\
&\hspace{110pt}+ u_{n,m} \left( s_0, \overline{\widetilde{X}}^{1,m,t,\overline{\xi},\overline{\mathfrak{a}}_0}_{s_0}, \ldots, \overline{\widetilde{X}}^{n,m,t,\overline{\xi},\overline{\mathfrak{a}}_0}_{s_0} \right) \bigg],
\end{align}
for any $t \in [0,s_0]$ and $\nu \in \mathcal{P}_2(\mathbb{R}^d \times A)$, where $\overline{\xi}=(\xi^1,\xi^2,\ldots,\xi^n) \in L^2(\Omega, \mathcal{F}_t, \mathbb{P}; \mathbb{R}^{dn})$, $\overline{\mathfrak{a}}_0=(\mathfrak{a}_0^1,\mathfrak{a}_0^2,\ldots,\mathfrak{a}_0^n) \in (\mathcal{M}_t)^n$ such that $\mathcal{L}(\overline{\xi},\overline{\mathfrak{a}}_0)=\nu \otimes \cdots \otimes \nu$ and $\overline{\widetilde{X}}^{m,t,\overline{\xi},\overline{\mathfrak{a}}_0}_s=\Big(\overline{\widetilde{X}}^{1,m,t,\overline{\xi},\overline{\mathfrak{a}}_0}_s,\ldots,\overline{\widetilde{X}}^{n,m,t,\overline{\xi},\overline{\mathfrak{a}}_0}_s\Big)$ is the solution to \eqref{eq. state perturbed by e BM and smoothing} on $[t,s_0]$ with $\overline{\alpha}=\overline{\mathfrak{a}}_0$, $\varepsilon=0$ and $b$ replaced by $\widetilde{b}^{\hspace{.7pt}i}_{n,m}$. For every $n, m \in \mathbb{N}$, $(t, \nu) \in [0, s_0] \times \mathcal{P}_2(\mathbb{R}^d\times A)$, we define $\widecheck{v}_{n,m}^{s_0}:=e^{t-t_0} v_{n,m}^{s_0}$ and also similarly define  $\widecheck{\widetilde{f}^{\hspace{.7pt}i}}_{n,m}$ and $\widecheck{u}_{n,m}$ from $\widetilde{f}_{n,m}^i$ and $u_{n,m}$, respectively. Let
\begin{align*}
\overline{v}_{n,m}^{s_0}(t,\overline{x},\overline{a})
:=\widetilde{v}_{n,m}^{s_0}
(t,\delta_{(x^1,a^1)}\otimes\cdots\otimes\delta_{(x^n,a^n)})

		\end{align*}
 for any $\overline{x}=\left(x^1, \ldots, x^n\right) \in \mathbb{R}^{dn}$ and $\overline{a}=\left(a^1, \ldots, a^n\right) \in A^n$, where
\begin{align}
		\widetilde{v}_{n,m}^{s_0}(t,\overline{\nu})
		:=& \dfrac{1}{n}\sum^n_{i=1}\mathbb{E}\Bigg[\int_t^{s_0} \widetilde{f}^{\hspace{.7pt}i}_{n,m}\left(s,\overline{\widetilde{X}}^{1,m,t,\overline{\xi},\overline{\mathfrak{a}}_0}_s,\ldots,
		\overline{\widetilde{X}}^{n,m,t,\overline{\xi},\overline{\mathfrak{a}}_0}_s,
		\mathfrak{a}_0^i\right)ds\nonumber \\
		&\hspace{110pt}+ u_{n,m}\left(\overline{\widetilde{X}}^{1,m,t,\overline{\xi},\overline{\mathfrak{a}}_0}_{s_0},\ldots,
		\overline{\widetilde{X}}^{n,m,t,\overline{\xi},\overline{\mathfrak{a}}_0}_{s_0}\right)\Bigg],
		\label{def. tilde v_e,n,m, with fixed control}
	\end{align}
 for any $t\in[0,s_0]$ and $\overline{\nu} \in \mathcal{P}_2\left(\mathbb{R}^{dn} \times A^n\right)$, where $\overline{\xi}$ and $\overline{\mathfrak{a}}_0$ satisfy $\mathcal{L}(\overline{\xi},\overline{\mathfrak{a}}_0)=\overline{\nu}$. Moreover, by \cite[Theorem A.8]{cosso_master_2022}, we deduce that $\widecheck{v}_{n,m}^{s_0}$ 
can be represented by 
\begin{align*}
\widecheck{v}_{n,m}^{s_0}(t,\nu)
=e^{t-t_0}\int_{\mathbb{R}^{dn}\times A^n}
\overline{v}_{n,m}^{s_0}(t,\overline{x},\overline{a})\nu(dx^1,da^1)\otimes\cdots\otimes
\nu(dx^n,da^n),
\end{align*}
and it could be shown by following the proofs of Lemma \ref{lem. classical sol. of smooth approx.}, Theorem \ref{thm v_e,n,m} and \cite[Theorem A.8]{cosso_master_2022} that 
\begin{enumerate}[(1).]
    \item $\overline{v}_{n, m}^{s_0} \in C^{1,2}\left(\left[0, s_0\right] \times (\mathbb{R}^{dn} \times A^n) \right)$ and $v_{n, m}^{s_0} \in C^{1,2}\left(\left[0, s_0\right] \times \mathcal{P}_2\left(\mathbb{R}^d \times A\right)\right)$;
    \item for any $i=1, \ldots, n$ and $(t,\overline{x},\overline{a}) \in\left[0, s_0\right] \times\mathbb{R}^{dn} \times A^n$, it holds that
$$
\left|\nabla_{x^i} \overline{v}_{n, m}^{s_0}(t,\overline{x},\overline{a})\right| \leq \frac{C_K}{n},
$$
where the constant $C_K \geq 0$ depends on $d$, $K$, $T$, but independent of $n, m$;
\item if $t \in [0,s_0]$ and $\nu \in \mathcal{P}_q\left(\mathbb{R}^d \times A\right)$ for some $q>2$,
then
\begin{align}
\label{v^s_n,m conv}
\lim _{n \rightarrow+\infty} \lim _{m \rightarrow+\infty} v_{n, m}^{s_0}(t, \nu)=v^{s_0}(t, \nu);
\end{align}
\item the function $v_{n,m}^{s_0}(t,\nu)$ solves the following equation classically:
\[
\left\{
\begin{aligned}
    &\partial_t u(t, \nu) + \overline{\mathbb{E}} \Bigg[ \sum_{i=1}^n \bigg\{ \frac{1}{n} \widetilde{f}^{\hspace{.7pt}i}_{n,m}(t, \overline{\xi}, \mathfrak{a}_0^i) 
    + \Big\langle\widetilde{b}_{n,m}^i (t, \overline{\xi}, \mathfrak{a}_0^i), \nabla_{x^i} \overline{v}_{n,m}^{s_0}(t, \overline{\xi}, \overline{\mathfrak{a}}_0)\Big\rangle  \\
    &\hspace{90pt} + \frac{1}{2} \text{tr} \left(\left[ (\sigma \sigma^\top) (t, \xi^i, \mathfrak{a}_0^i)+(\sigma^0\sigma^{0;\top})(t,\xi^i)\right]  \nabla_{x^ix^i}^2 \overline{v}_{n,m}^{s_0}(t, \overline{\xi}, \overline{\mathfrak{a}}_0)\right) \bigg\}\\
    &\hspace{60pt}+\dfrac{1}{2}
				\sum^n_{i,j=1,i\neq j}\textup{tr}\Big[\sigma^0(t,\xi^i)\sigma^{0;\top}(t,\xi^j)\nabla_{x^ix^j}^2 \overline{v}_{n,m}^{s_0}(t, \overline{\xi}, \overline{\mathfrak{a}}_0)\Big]\Bigg] =0; \\
    &u(s_0, \nu) = \overline{\mathbb{E}}  [u_{n,m}(s_0, \overline{\xi})],
\end{aligned}
\right.
\]
for any $t \in [0,s_0)$ and $\nu \in \mathcal{P}_2(\mathbb{R}^d \times A)$, where $\overline{\xi}=(\xi^1,\xi^2,\ldots,\xi^n) \in L^2(\Omega, \mathcal{F}_t, \mathbb{P}; \mathbb{R}^{dn})$, $\overline{\mathfrak{a}}_0=(\mathfrak{a}_0^1,\mathfrak{a}_0^2,\ldots,\mathfrak{a}_0^n) \in (\mathcal{M}_t)^n$ such that $\mathcal{L}(\overline{\xi},\overline{\mathfrak{a}}_0)=\nu \otimes \ldots \otimes \nu$.
\end{enumerate}
We now return to the hypothesis \eqref{1450}, with $\mu_0$ and $\nu_0$ mentioned therein. Let $l_0:=v^{s_0}(t_0,\nu_0)-u_2(t_0,\mu_0)>0$. For small enough $\delta>0$ depending on $M_{2}(\nu_0)$ and $l_0$ only, we have $v^{s_0}(t_0,\nu_0)-u_2(t_0,\mu_0)-\delta M_{2}(\nu_0)\geq l_0/2$ and thus $v^{s_0}_{n,m}(t_0,\nu_0)-u_2(t_0,\mu_0)-\delta M_{2}(\nu_0)\geq l_0/3$, where $v^{s_0}_{n,m}$ is defined in \eqref{v^s_n,m}, and this holds for large enough $n$, $m\in \mathbb{N}$ depending on $\delta$, $M_{2}(\nu_0)$ and $l_0$ only, by \eqref{v^s_n,m conv}. Thus, it holds that 
\begin{equation}\label{eq:cpt1}
\displaystyle\sup_{(t,\nu)\in [0,T] \times \mathcal{P}_2(\mathbb{R}^d\times A)} \widecheck{v}^{s_0}_{n,m}(t,\nu)-\widecheck{u}_2(t,\mu)-\delta M_{2}(\nu)\geq l_0/3,
\end{equation}
where $\mu$ is the marginal of $\nu$ on $\mathbb{R}^d$, for large enough $n$, $m\in \mathbb{N}$ depending on $\delta$, $M_{2}(\nu_0)$ and $l_0$ only. By the compactness of \begin{align*}
\widetilde{U}^2_{\delta, n,m}:=\scalerel*[5pt]{\big\{}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big\{}}}(t,\nu) \in [0,T]\times\mathcal{P}_2(\mathbb{R}^d \times A):\widecheck{v}^{s_0}_{n,m}(t,\nu)-\widecheck{u}_2(t,\mu)-\delta M_{2}(\nu) \geq l_0/3\scalerel*[5pt]{\big\}}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big\}}}},
\end{align*}
and the upper semicontinuity of $\widecheck{v}^{s_0}_{n,m}-\widecheck{u}_2-\delta M_{2}$, we argue as in Part 1A to deduce that there exists $(\widetilde{t},\widetilde{\nu}) \in [0,T] \times \widetilde{U}^2_{\delta, n,m}$ such that the maximum of $\widecheck{v}^{s_0}_{n,m}-\widecheck{u}_2-\delta M_{2}$ is attained at $(\widetilde{t},\widetilde{\nu})$. We note that this maximum point depends on $\delta, n,m$. If $\widetilde{t} = s_0=T$, then we proceed as in Step 1B to get a contradiction. If $\widetilde{t} = s_0<T$, then \begin{align*}
	(v^{s_0}_{n,m}-u_2-\delta  M_2)(t_0,\nu_0) = (\widecheck{v}^{s_0}_{n,m}-\widecheck{u}_2-\delta  M_2)(t_0,\nu_0)
			&\leq  \widecheck{v}^{s_0}_{n,m}(s_0,\widetilde{\nu})-\widecheck{u}_2(s_0,\widetilde{\nu}) 
			-\delta  M_2(\widetilde{\nu})\nonumber\\
   &\leq \widecheck{v}^{s_0}_{n,m}(s_0,\widetilde{\nu})-\widecheck{u}_2(s_0,\widetilde{\nu})\to 0,
\end{align*}
as $m \to \infty$ then $n\to \infty$, by using the definition of $\widecheck{v}_{n,m}^{s_0}:=e^{t-t_0} v_{n,m}^{s_0}$ and that of $v_{n,m}^{s_0}$ in \eqref{v^s_n,m}. If $\widetilde{t}<s_0$, we apply Definition \ref{def. of vis sol} of supersolution and put $\varphi=\widecheck{v}_{n,m}^{s_0}-\delta M_2-M_*$ in \eqref{2214}, with $M_* \in \mathbb{R}$ such that $ \widecheck{v}_{n,m}^{s_0}-\widecheck{u}_2 -\delta M_2-M_*$ attains the maximum with a value of $0$ at $(\widetilde{t},\widetilde{\nu})$. Then we proceed as in Step 1C and utilize items (1)-(4) in the above to draw a contradiction and conclude the proof.

The bounds of $f^i_{n,m}$ and $g^i_{n,m}$ in assertion (1) are obvious by the definitions in \eqref{def. approx of b}-\eqref{def. approx of g} and Assumption \ref{assume:A}. For the bound of $b^i_{n,m}$ in assertion (1), we have
\begin{align*}
|b^i_{n,m}(t,\overline{x},a)|&\leq Km^{dn}\int_{\mathbb{R}^{dn}}
[1+|x^i|^\rho+|y^i|^\rho]\prod^n_{k=1}\Phi(my^k)dy^k\\
&\leq K\left(1+|x^i|^\rho+m^{-\rho}\int_{\mathbb{R}^{d}}
|y^i|^\rho\Phi(y^i)dy^i\right)\\
&\leq  K\scalerel*[5pt]{\big(}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big(}}}1+C_{\Phi,\rho}m^{-\rho}+|x^i|^\rho\scalerel*[5pt]{\big)}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big)}}}.
\end{align*}

We prove assertion (2) for $g$ by considering
\begin{align*}
\scalerel*[5pt]{\big|}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big|}}}g(x^i, \widehat{\mu}^{n,\overline{x}}) - g^i_{n,m} (\overline{x})\scalerel*[5pt]{\big|}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big|}}}
\leq m^{dn} \int_{\mathbb{R}^{dn}} \bigg| g(x^i, \widehat{\mu}^{n,\overline{x}}) 
- g \bigg( x^i -y^i, \frac{1}{n} \sum_{j=1}^{n} \delta_{x^j-y^j} \bigg) \bigg| \prod^n_{k=1}\Phi(my^k) dy^k.
\end{align*}
Using the Lipschitz continuity of $g$ in Assumption \ref{assume:A} and the fact that
\begin{align}
\mathcal{W}_1 \bigg( \widehat{\mu}^{n,\overline{x}},  \frac{1}{n} \sum_{j=1}^{n} \delta_{x^j-y^j} \bigg) 
&= \mathcal{W}_1  \bigg( \frac{1}{n} \sum_{j=1}^{n} \delta_{x^j}, \frac{1}{n} \sum_{j=1}^{n} \delta_{x^j - y^j} \bigg) \nonumber\\
&\leq \int_{\mathbb{R}^d\times \mathbb{R}^d} |x-y|
\left[\frac{1}{n} \sum_{j=1}^{n} \delta_{(x^j,x^j - y^j)}(dx,dy)\right] \nonumber\\
&= \frac{1}{n} \sum_{j=1}^{n} |y^j|,
\label{1701}
\end{align}
we obtain that
\begin{align*}
\scalerel*[5pt]{\big|}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big|}}}g(x^i, \widehat{\mu}^{n,\overline{x}}) - g^i_{n,m} (\overline{x})\scalerel*[5pt]{\big|}{ 
		\ensurestackMath{\addstackgap[1.5pt]{\big|}}}
\leq K m^{dn} \int_{\mathbb{R}^{dn}} \bigg( |y^i| + \frac{1}{n} \sum_{j=1}^{n} |y^j| \bigg) \prod_{k=1}^{n} \Phi(my^k) dy^k.
\end{align*}
We prove assertion (2) for $b$ by considering (the proof for $f$ is exactly the same)
\begin{align*}
&|b(t, x^i, \widehat{\mu}^{n,\overline{x}}, a) - b_{n,m}^i (t, \overline{x}, a)| \\
&\leq m^{dn+1} \int_{\mathbb{R}^{dn+1}} \left| b(t, x^i, \widehat{\mu}^{n,\overline{x}}, a) - b \bigg( T \wedge (t-s)^+, x^i - y^i, \frac{1}{n} \sum_{j=1}^{n} \delta_{x^j - y^j}, a \bigg) \right| \phi(ms) \prod_{k=1}^{n} \Phi(my^k) dy^k ds\\
&\leq m \int_{\mathbb{R}} \left| b(t, x^i, \widehat{\mu}^{n,\overline{x}}, a) 
- b \left( T \wedge (t-s)^+, x^i, \widehat{\mu}^{n,\overline{x}}, a \right) \right| \phi(ms) ds \\
&\hspace{10pt}+ m^{dn+1} \int_{\mathbb{R}^{dn+1}} \left| b \left( T \wedge (t-s)^+, x^i, \widehat{\mu}^{n,\overline{x}}, a \right) - b \bigg( T \wedge (t-s)^+, x^i - y^i, \frac{1}{n} \sum_{j=1}^{n} \delta_{x^j - y^j}, a \bigg) \right|\cdot\\
&\hspace{335pt}\phi(ms) \prod_{j=1}^{n} \Phi(my^j) dy^j ds.
\end{align*}
The inequality in \eqref{1701} and Assumption \ref{assume:A} imply that
\begin{align*}
&|b(t, x^i, \widehat{\mu}^{n,\overline{x}}, a) - b_{n,m}^i (t, \overline{x}, a)| \\
&\leq Km \int_{\mathbb{R}} \left|t- (T \wedge (t-s)^+) ) \right|^\beta \phi(ms) ds 
+ K m^{dn} \int_{\mathbb{R}^{dn}} \bigg( |y^i| + \frac{1}{n} \sum_{j=1}^{n} |y^j| \bigg) \prod_{k=1}^{n} \Phi(my^k) dy^k.
\end{align*}
For the proof of assertion (3) for $g$ (the proofs for $f$ and $b$ are exactly the same), we let $\overline{x}$, $\overline{z} \in \mathbb{R}^{dn}$ and estimate
\begin{align*}
&|g_{n,m}^i (\overline{x}) - g_{n,m}^i (\overline{z})| \\
&\leq m^{dn} \int_{\mathbb{R}^{dn}} \bigg| g \bigg( x^i-y^i, \frac{1}{n} \sum_{j=1}^{n} \delta_{x^j-y^j} \bigg) 
- g \bigg( z^i-y^i, \frac{1}{n} \sum_{j=1}^{n} \delta_{z^j-y^j} \bigg) \bigg|  \prod_{k=1}^{n} \Phi(my^k) dy^k.
\end{align*}
Then the inequality in \eqref{1701}  yields that
\begin{align*}
|g_{n,m}^i (\overline{x}) - g_{n,m}^i (\overline{z})| 
&\leq K m^{dn} \int_{\mathbb{R}^{dn}}\bigg[ |x^i - z^i| + \frac{1}{n} \sum_{j=1}^{n} |x^j - z^j| \bigg]\prod_{k=1}^{n} \Phi(my^k) dy^k\\
&= K \bigg[ |x^i - z^i| + \frac{1}{n} \sum_{j=1}^{n} |x^j - z^j| \bigg].
\end{align*}
Finally, assertion (4) follows immediately from assertion (2).

\noindent{\bf Step 1. Lipschitz continuity of $\overline{v}_{\varepsilon,n,m}(t,\overline{x})$ in $\overline{x}$:}                                                                                                                           
    Note that the identity \cite[(A.21)]{cosso_master_2022} may contain potential typographical errors, so we reproduce the proof of the Lipschitz continuity property here for the case involving common noise. We aim to establish that
\begin{align*}
\left| \overline{v}_{\varepsilon,n,m}(t, \overline{x}) - \overline{v}_{\varepsilon,n,m}(t, \overline{z}) \right| \leq \frac{C_4}{n} \left| \overline{x} - \overline{z} \right|,
\end{align*}
