\begin{align}
&\left| \overline{v}_{\varepsilon,n,m}(t, \overline{x}) - \overline{v}_{\varepsilon,n,m}(t, \overline{z}) \right| \nonumber\\
&\leq 2K \sup_{\overline{\alpha} \in \overline{\mathcal{A}}^n_t} \frac{1}{n} \sum_{i=1}^{n} \mathbb{E} \left[ \int_{t}^{T} \left| \overline{X}_{s}^{i,m,\varepsilon,t,\overline{x},\overline{\alpha}} - \overline{X}_{s}^{i,m,\varepsilon,t,\overline{z},\overline{\alpha}} \right| ds + \left| \overline{X}_{T}^{i,m,\varepsilon,t,\overline{x},\overline{\alpha}} - \overline{X}_{T}^{i,m,\varepsilon,t,\overline{z},\overline{\alpha}} \right| \right]\nonumber\\
&\leq\dfrac{C_{d,K,T}}{n}|z^1-x^1|.
\label{1606}
\end{align}

\noindent{\bf Step 2. $\overline{v}_{\varepsilon,n,m}(t,\overline{x})$ is the unique classical solution of \eqref{eq. bellman bar v_e,n,m}:} In this step, the definition of viscosity solution is referred to the usual Crandall-Lions' definition as the equation is on $[0,T] \times \mathbb{R}^{dn}$ instead of the Wasserstein space. First note that the volatility term (the second-order term) of equation \eqref{eq. bellman bar v_e,n,m} can be written as $\frac{1}{2}\text{tr}\big[Q \nabla_{\bar{x}\bar{x}}^2 v\big]$, with 
\begin{align*}






    Q &:= \begin{pmatrix}
        \sigma\sigma^\top(t,x^1,a^1) &0 &\ldots &0\\
        0 &\sigma\sigma^\top(t,x^2,a^2) &\ldots &0\\
        \vdots &\vdots&\ldots&\vdots   \\
        0 &0 &\ldots &\sigma\sigma^\top(t,x^n,a^n)
    \end{pmatrix}
    +\varepsilon^2I_{dn}+\begin{pmatrix}
        \sigma^0(t,x^1)\\
        \sigma^0(t,x^2)\\
        \vdots\\
        \sigma^0(t,x^n)
    \end{pmatrix}\begin{pmatrix}
        \sigma^0(t,x^1)\\
        \sigma^0(t,x^2)\\
        \vdots\\
        \sigma^0(t,x^n)
    \end{pmatrix}^\top.
\end{align*} It can be easily shown that $Q$ is positive definite. Consequently, we have $Q \nabla_{\bar{x}\bar{x}}^2 \overline{v}_{\varepsilon,n,m} = \Sigma\Sigma^\top \nabla_{\bar{x}\bar{x}}^2\overline{v}_{\varepsilon,n,m}$, where $\Sigma$ satisfies $\Sigma\Sigma^\top \geq \varepsilon^2 I_{dn}$. Using \cite[Chatper 4.6, Theorem 6.2]{yong1999stochastic}, we conclude that $\overline{v}_{\varepsilon,n,m}$ is the unique viscosity solution of the Bellman equation \eqref{eq. bellman bar v_e,n,m}. Due to the $1/2$-H\"older continuity of $\overline{v}_{\varepsilon,n,m}(t,\overline{x})$ in $t$, Lipschitz continuity in $\overline{x}$ as established in \eqref{1606} and the boundedness of the non-homogeneous term $f^i_{n,m}$ of \eqref{eq. bellman bar v_e,n,m}, we consider the equation \eqref{eq. bellman bar v_e,n,m} on $[0,T] \times B_R \subset [0,T] \times \mathbb{R}^{dn}$ with the parabolic boundary value of $\overline{v}_{\varepsilon,n,m}(t,\overline{x})$. For this localized equation, we can apply \cite[Theorem 8.4]{CKS00} to obtain a unique strong solution $\overline{v}^\dagger_{\varepsilon,n,m}(t,\overline{x})$ which lies in $C^{\frac{1+\alpha}{2},1+\alpha}_{\textup{loc}}([0,T) \times B_R) \cap C([0,T] \times \overline{B_R})$. We see that $\overline{v}^\dagger_{\varepsilon,n,m}(t,\overline{x})$ is also the viscosity solution to \eqref{eq. bellman bar v_e,n,m} in $[0,T] \times B_R$ under the usual Crandall-Lions' definition, by \cite[Proposition 2.10]{CKS00}. Therefore, as the viscosity solution to \eqref{eq. bellman bar v_e,n,m} on $[0,T] \times \mathbb{R}^{dn}$ is unique, then we see that $\overline{v}_{\varepsilon,n,m}=\overline{v}^\dagger_{\varepsilon,n,m} \mathds{1}_{[0,T]\times B_R}
+\overline{v}_{\varepsilon,n,m} \mathds{1}_{[0,T]\times (\mathbb{R}^{dn}\setminus B_R)}$ for any $R>0$. In other words, $\overline{v}_{\varepsilon,n,m}$ is continuously differentiable with respect to $\overline{x}$ on $\mathbb{R}^{dn} \times[0,T)$. We consider another equation
\begin{equation}
\left\{
\begin{aligned}
				&\partial_t u(t,\overline{x})
				+\sup_{\overline{a} \in A^n}\Bigg\{\dfrac{1}{n}\sum^n_{i=1}f^i_{n,m}(t,\overline{x},a^i)
				+\dfrac{1}{2}\sum^n_{i=1}\textup{tr}\left[\Big((\sigma\sigma^\top)(t,x^i,a^i)+\sigma^0\sigma^{0;\top}(t,x^i)+\varepsilon^2I_d\Big)\nabla_{x^ix^i}^2
				u(t,\overline{x})\right]\\ 
				&\hspace{80pt}+\sum^n_{i=1}\left\langle b^i_{n,m}(t,\overline{x},a^i)
				,\nabla_{x^i}\overline{v}_{\varepsilon,n,m}(t,\overline{x})\right\rangle
				+\frac{1}{2}\sum_{i,j=1,i\neq j}^n\textup{tr}\Big[\sigma^0(t,x^i)\sigma^{0;\top}(t,x^j)\nabla_{x^ix^j}^2u(t,\overline{x})\Big]\Bigg\}\\
				&=0\hspace{5pt} \text{in $[0,T) \times\mathbb{R}^{dn}$};\\
				&u(T,\overline{x})
				=\dfrac{1}{n}\sum^n_{i=1}g^i_{n,m}(\overline{x})
				\hspace{5pt} \text{ in $\mathbb{R}^{dn}$}.
			\end{aligned}
			\right.   
			\label{eq. bellman bar v_e,n,m wit fixed term}
\end{equation}
In the above equation, we note the unknown $u$ is only involved in the time differentiation and the second-order spatial differentiation, the remaining terms are all in $C^{0,\alpha}([0,T)\times B_{R'})$ for any $R'>0$ and some $\alpha>0$. As $\overline{v}_{\varepsilon,n,m}$ is the unique viscosity solution to \eqref{eq. bellman bar v_e,n,m} on $[0,T] \times \mathbb{R}^{dn}$ under the usual Crandall-Lions' definition, it is also a viscosity solution to \eqref{eq. bellman bar v_e,n,m wit fixed term} under the usual Crandall-Lions' definition as it is continuously differentiable on $\overline{x}$. By considering the equation in \eqref{eq. bellman bar v_e,n,m wit fixed term} in a local region with the parabolic boundary value $\overline{v}_{\varepsilon,n,m}$, we can apply \cite[Theorem 5.2]{M19} to find a classical solution $\overline{v}^*_{\varepsilon,n,m}(t,\overline{x})$ to \eqref{eq. bellman bar v_e,n,m wit fixed term} on that local region. As the viscosity solution of \eqref{eq. bellman bar v_e,n,m wit fixed term} on $[0,T] \times \mathbb{R}^{dn}$ is unique by \cite[Chatper 4.6, Theorem 6.2]{yong1999stochastic}, we see that $\overline{v}_{\varepsilon,n,m}(t,\overline{x})=\overline{v}^*_{\varepsilon,n,m}(t,\overline{x})$ is actually classical.\\
\hfill\\
\noindent {\bf Step 3. Bounds of derivatives of $\overline{v}_{\varepsilon,n,m}(t,\overline{x})$:} Note that $\overline{v}_{\varepsilon,n,m}(t,\overline{x})\in C^{1,2}([0,T]\times\mathbb{R}^{dn})$, the boundedness of the first-order derivative with respect to $\overline{x}$ follows from \eqref{1606}, while the boundedness of the second-order derivative is established using \cite[Chapter 4.7, Theorem 4]{K08}.
